    [2949] = { description = { from = "legacy", text = "Horde step required before Nogg's Ring Redo." }, hints = { { field = "startedBy", from = "legacy", text = "The Sparklematic 5200, inside Gnomeregan" } }, objective = { from = "legacy", text = "Take the Brilliant Gold Ring to Nogg in Orgrimmar." } },
    [2950] = { objective = { from = "legacy", text = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar." } },
    [2951] = { hints = { { field = "endedBy", from = "legacy", text = "The Sparklematic 5200, inside Gnomeregan" }, { field = "startedBy", from = "legacy", text = "The Sparklematic 5200, inside Gnomeregan" } }, objective = { from = "legacy", text = "Insert a Grime-Encrusted Object into the Sparklematic 5200, with three silver coins to start the machine." } },
    [2962] = { objective = { from = "legacy", text = "Bring High Potency Radioactive Fallout and the Heavy Leaden Collection Phial back to Ozzie. The fallout collapses quickly." } },
    [2988] = { objective = { from = "legacy", text = "Check the cages at the two Witherbark villages, then return to Gryphon Master Talonaxe." } },
    [2989] = { objective = { from = "legacy", text = "Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe." } },
    [2990] = { objective = { from = "legacy", text = "Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands." } },
    [2991] = { objective = { from = "legacy", text = "Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands." } },
    [3042] = { objective = { from = "legacy", text = "Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan." } },
    [3341] = { objective = { from = "legacy", text = "Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull." } },
    [3373] = { hints = { { field = "endedBy", from = "legacy", text = "Essence Font, Sunken Temple" }, { field = "startedBy", from = "legacy", text = "Essence of Eranikus (drops from the Shade of Eranikus)" } }, objective = { from = "legacy", text = "Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple." } },
    [3444] = { objective = { from = "legacy", text = "Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet." } },
    [3446] = { hints = { { field = "endedBy", from = "legacy", text = "Altar of Hakkar, Sunken Temple" } }, objective = { from = "legacy", text = "Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows." } },
    [3447] = { hints = { { field = "endedBy", from = "legacy", text = "Altar of Hakkar, Sunken Temple" } }, objective = { from = "legacy", text = "Travel into the Sunken Temple and discover the secret hidden in the circle of statues." } },
    [3520] = { objective = { from = "legacy", text = "Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port." } },
    [3523] = { objective = { from = "legacy", text = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him." } },
    [3525] = { hints = { { field = "endedBy", from = "legacy", text = "Belnistrasz's Brazier, Razorfen Downs" } }, objective = { from = "legacy", text = "Escort Belnistrasz to the Quilboar's idol in Razorfen Downs. Protect Belnistrasz while he performs the ritual to shut down the idol." } },
    [3527] = { objective = { from = "legacy", text = "Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris." } },
    [3528] = { objective = { from = "legacy", text = "Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris." } },
    [3636] = { objective = { from = "legacy", text = "Archbishop Benedictus wants you to slay Amnennar the Coldbringer in Razorfen Downs." } },
    [3701] = { objective = { from = "legacy", text = "Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information." } },
    [3702] = { objective = { from = "legacy", text = "Listen to Royal Historian Archesonus recant the history of Thaurissan." } },
    [3765] = { description = { from = "legacy", text = "Optional Alliance breadcrumb leading to Researching the Corruption." }, objective = { from = "legacy", text = "Travel to Gershala Nightwhisper in Auberdine, Darkshore." } },
    [3801] = { objective = { from = "legacy", text = "Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major." }, warning = { from = "legacy", text = "You have to be dead to talk to this guy. He's in Blackrock Mountain, in a room while walking the chain down to BRD." } },
    [3802] = { objective = { from = "legacy", text = "Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright." } },
    [3906] = { objective = { from = "legacy", text = "Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment." } },
    [3907] = { objective = { from = "legacy", text = "Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart." } },
    [3981] = { objective = { from = "legacy", text = "Find Commander Gor'shak in Blackrock Depths. You recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort." } },
    [3982] = { objective = { from = "legacy", text = "Defend Gor'shak." } },
    [4001] = { objective = { from = "legacy", text = "Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar. You recall Gor'shak mentioning that Kharan is being held in a cell nearby." } },
    [4002] = { objective = { from = "legacy", text = "Speak with Thrall if you are prepared to take on the mission he has planned." } },
    [4003] = { objective = { from = "legacy", text = "Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell." } },
    [4024] = { objective = { from = "legacy", text = "Travel to Blackrock Depths and slay Bael'Gar. Use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence. Return the Encased Fiery Essence to Cyrus Therepentous." } },
    [4061] = { objective = { from = "legacy", text = "Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania. You recall Theodora mentioning the golems and elementals of that region as being a source for these shards." } },
    [4062] = { objective = { from = "legacy", text = "Take the Elemental Shard Sample to Lotwil Veriatus. You recall Theodora saying that Lotwil was stationed in a camp to the east." } },
    [4063] = { objective = { from = "legacy", text = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach." } },
    [4081] = { hints = { { field = "startedBy", from = "legacy", text = "Wanted Poster, Kargath, Badlands" } }, objective = { from = "legacy", text = "Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete." } },
    [4082] = { hints = { { field = "startedBy", from = "legacy", text = "Wanted Poster, Kargath, Badlands" } }, objective = { from = "legacy", text = "Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete." } },
    [4083] = { objective = { from = "legacy", text = "Bring Gloom'rel 2 Star Rubies, 20 Gold Bars and 10 Truesilver Bars, then place them in the Spectral Chalice in the Summoners' Tomb." } },
    [4121] = { objective = { from = "legacy", text = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge. You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody. You will also be required to hand over your Thorium Shackles to Lexlort." } },
    [4122] = { objective = { from = "legacy", text = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress. When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody." } },
    [4123] = { objective = { from = "legacy", text = "Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes." } },
    [4126] = { objective = { from = "legacy", text = "Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos." } },
    [4128] = { objective = { from = "legacy", text = "Speak with Ragnar Thunderbrew." } },
    [4132] = { objective = { from = "legacy", text = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete." } },
    [4133] = { objective = { from = "legacy", text = "Speak with Shadowmage Vivian Lagrave in Kargath." } },
    [4134] = { objective = { from = "legacy", text = "Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath." } },
    [4136] = { objective = { from = "legacy", text = "Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes." } },
    [4141] = { objective = { from = "legacy", text = "Collect 15 Bloodpetals and return to Muigin." } },
    [4142] = { objective = { from = "legacy", text = "Take a Bloodpetal to Gregan Brewspewer in Feralas." } },
    [4143] = { objective = { from = "legacy", text = "Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater." } },
    [4145] = { objective = { from = "legacy", text = "Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge." } },
    [4146] = { objective = { from = "legacy", text = "Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge." } },
    [4147] = { objective = { from = "legacy", text = "Travel to Marvon Rivetseeker's workshop in Ratchet." } },
    [4182] = { objective = { from = "legacy", text = "Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete." } },
    [4183] = { objective = { from = "legacy", text = "Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon." } },
    [4184] = { objective = { from = "legacy", text = "Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon. Bolvar resides in Stormwind Keep." } },
    [4185] = { objective = { from = "legacy", text = "Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor." } },
    [4186] = { objective = { from = "legacy", text = "Take Bolvar's Decree to Magistrate Solomon in Lakeshire." } },
    [4201] = { objective = { from = "legacy", text = "Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths." } },
    [4223] = { objective = { from = "legacy", text = "Speak with Marshal Maxwell in the Burning Steppes." } },
    [4224] = { objective = { from = "legacy", text = "Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task. You recall Marshal Maxwell telling you to search for him in a cave to the north." } },
    [4241] = { objective = { from = "legacy", text = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor. You recall Ragged John talking about Windsor being dragged off to a prison." } },
    [4242] = { objective = { from = "legacy", text = "Give Marshal Maxwell the bad news." } },
    [4262] = { objective = { from = "legacy", text = "Slay Overmaster Pyron and return to Jalinda Sprig. You recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?" } },
    [4263] = { objective = { from = "legacy", text = "Find Lord Incendius in Blackrock Depths and destroy him!" } },
    [4264] = { hints = { { field = "startedBy", from = "legacy", text = "Drops from Dark Iron dwarves in Blackrock Depths once Abandoned Hope is turned in" }, { field = "startedBy", from = "legacy", text = "A Crumpled Up Note (drops from Dark Iron dwarves)" } }, objective = { from = "legacy", text = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all." } },
    [4282] = { objective = { from = "legacy", text = "Return Marshal Windsor's Lost Information. Marshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge." } },
    [4286] = { objective = { from = "legacy", text = "Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions." } },
    [4322] = { objective = { from = "legacy", text = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed." } },
    [4324] = { objective = { from = "legacy", text = "Speak with Yuka Screwspigot in the Burning Steppes." } },
    [4341] = { objective = { from = "legacy", text = "Travel to Blackrock Depths and find Kharan Mighthammer. The King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison." } },
    [4342] = { objective = { from = "legacy", text = "Listen as Kharan Mighthammer tells his story." } },
    [4361] = { objective = { from = "legacy", text = "Return to Ironforge and deliver the bad news to King Magni Bronzebeard." } },
    [4362] = { objective = { from = "legacy", text = "Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan." } },
    [4701] = { objective = { from = "legacy", text = "Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg." } },
    [4724] = { objective = { from = "legacy", text = "Slay Halycon, pack mistress of the Bloodaxe worg." } },
    [4726] = { objective = { from = "legacy", text = "Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes." } },
    [4729] = { objective = { from = "legacy", text = "Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler." } },
    [4734] = { objective = { from = "legacy", text = "Use the Eggscilloscope Prototype on an egg in the Rookery." } },
    [4735] = { objective = { from = "legacy", text = "Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes." } },
    [4742] = { hints = { { field = "requiredItemIDs", from = "legacy", text = "Dropped by Highlord Omokk, Lower Blackrock Spire" }, { field = "requiredItemIDs", from = "legacy", text = "Dropped by War Master Voone, Lower Blackrock Spire" }, { field = "requiredItemIDs", from = "legacy", text = "Dropped by Overlord Wyrmthalak, Lower Blackrock Spire" }, { field = "requiredItemIDs", from = "legacy", text = "Random drop from Blackrock Spire trash" } }, objective = { from = "legacy", text = "Find the three gemstones of command: the Gemstone of Smolderthorn, Gemstone of Spirestone and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan. The generals are War Master Voone of the Smolderthorn, Highlord Omokk of the Spirestone and Overlord Wyrmthalak of the Bloodaxe." } },
    [4743] = { objective = { from = "legacy", text = "Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake Emberstrife and beat him until his will is broken, place the Unforged Seal of Ascension before him, then use the Orb of Draconic Energy on him and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension." } },
    [4764] = { objective = { from = "legacy", text = "Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes." } },
    [4766] = { objective = { from = "legacy", text = "Speak with Mayara Brightwing in the Burning Steppes." } },
    [4768] = { objective = { from = "legacy", text = "Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath." } },
    [4769] = { objective = { from = "legacy", text = "Speak with Shadowmage Vivian Lagrave." } },
    [4771] = { objective = { from = "legacy", text = "Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink." } },
    [4787] = { objective = { from = "legacy", text = "Bring the Ancient Egg to Yeh'kinya in Tanaris." } },
    [4788] = { objective = { from = "legacy", text = "Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris." } },
    [4808] = { objective = { from = "legacy", text = "Give Tinkee's Letter to Felnok Steelspring." } },
    [4809] = { objective = { from = "legacy", text = "Bring 8 Uncracked Chillwind Horns to Felnok Steelspring." } },
    [4810] = { objective = { from = "legacy", text = "Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes." } },
    [4862] = { objective = { from = "legacy", text = "Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler. By the sound of it, these eggs could be found near spiders." } },
    [4866] = { objective = { from = "legacy", text = "In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Return to Ragged John while poisoned so that he can 'milk' you." } },
    [4867] = { objective = { from = "legacy", text = "Read Warosh's Scroll. Bring Warosh's Mojo to Warosh." } },
    [4903] = { objective = { from = "legacy", text = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished." } },
    [4907] = { objective = { from = "legacy", text = "Speak with Tinkee Steamboil." } },
    [4941] = { objective = { from = "legacy", text = "Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall. You recall having seen Eitrigg in Thrall's chamber." } },
    [4974] = { objective = { from = "legacy", text = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar." } },
    [4981] = { objective = { from = "legacy", text = "Travel to Blackrock Spire and find out what happened to Bijou." } },
    [4982] = { objective = { from = "legacy", text = "Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city." } },
    [5001] = { objective = { from = "legacy", text = "Find Bijou's Belongings and return them to her. Good luck!" } },
    [5002] = { objective = { from = "legacy", text = "Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell." } },
    [5047] = { hints = { { field = "startedBy", from = "legacy", text = "From The Beast's corpse, Upper Blackrock Spire" } }, objective = { from = "legacy", text = "Talk to Malyfous Darkhammer in Everlook." } },
    [5065] = { objective = { from = "legacy", text = "Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris." } },
    [5081] = { objective = { from = "legacy", text = "Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done." } },
    [5089] = { hints = { { field = "startedBy", from = "legacy", text = "Dropped by Overlord Wyrmthalak in Lower Blackrock Spire" }, { field = "startedBy", from = "legacy", text = "General Drakkisath's Command (drops from Overlord Wyrmthalak)" } }, objective = { from = "legacy", text = "Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes." } },
    [5102] = { objective = { from = "legacy", text = "Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done." } },
    [5122] = { objective = { from = "legacy", text = "Retrieve the Medallion of Faith from Malor the Zealous in the Scarlet Bastion and bring it back to Aurius." } },
    [5125] = { objective = { from = "legacy", text = "Give Aurius the Medallion of Faith; he joins the fight against Baron Rivendare. Claim his reward after the battle." } },
    [5127] = { objective = { from = "legacy", text = "Travel to Blackrock Spire, slay Goraluk Anvilcrack and use the Blood Stained Pike on his corpse. Also find the Unforged Rune Covered Breastplate. Return the Soul Stained Pike and the breastplate to Lorax in Winterspring." } },
    [5160] = { objective = { from = "legacy", text = "Travel to Winterspring and find Haleh. Give her Awbee's scale." } },
    [5212] = { objective = { from = "legacy", text = "Recover 20 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample." } },
    [5213] = { objective = { from = "legacy", text = "Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink." } },
    [5214] = { objective = { from = "legacy", text = "Find Fras Siabi's smoke shop in Stratholme and recover a box of Siabi's Premium Tobacco. Return to Smokey LaRue when the job is done." } },
    [5243] = { objective = { from = "legacy", text = "Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid." } },
    [5244] = { objective = { from = "legacy", text = "Speak with Jaron Stoneshaper in Starfall Village." } },
    [5245] = { objective = { from = "legacy", text = "Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands." } },
    [5246] = { objective = { from = "legacy", text = "Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands." } },
    [5247] = { objective = { from = "legacy", text = "Bring an Enchanted Thorium Bar, 5 Crystal Restore, and a Vial of Dire Water to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands." } },
    [5250] = { objective = { from = "legacy", text = "Find Starfall in Winterspring and speak with Wynd Nightchaser." } },
    [5251] = { objective = { from = "legacy", text = "Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive." } },
    [5262] = { hints = { { field = "startedBy", from = "legacy", text = "Head of Balnazzar (drops from Balnazzar)" } }, objective = { from = "legacy", text = "Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands." } },
    [5263] = { objective = { from = "legacy", text = "Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff." } },
    [5281] = { objective = { from = "legacy", text = "Find Egan. You only know that he was last seen around Stratholme." } },
    [5282] = { objective = { from = "legacy", text = "Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs! Free 15 Restless Souls and return to Egan." } },
    [5341] = { objective = { from = "legacy", text = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task." } },
    [5343] = { objective = { from = "legacy", text = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task." } },
    [5382] = { objective = { from = "legacy", text = "Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete." } },
    [5384] = { objective = { from = "legacy", text = "Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul. Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff." } },
    [5461] = { objective = { from = "legacy", text = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke." } },
    [5462] = { objective = { from = "legacy", text = "Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered." } },
    [5463] = { hints = { { field = "endedBy", from = "legacy", text = "Menethil's Gift, Stratholme" } }, objective = { from = "legacy", text = "Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground." } },
    [5464] = { objective = { from = "legacy", text = "Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands." } },
    [5465] = { objective = { from = "legacy", text = "Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake." } },
    [5466] = { objective = { from = "legacy", text = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke." } },
    [5515] = { objective = { from = "legacy", text = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff." } },
    [5518] = { objective = { from = "legacy", text = "Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul." } },
    [5522] = { objective = { from = "legacy", text = "Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands." } },
    [5525] = { objective = { from = "legacy", text = "Find a Gordok Shackle Key on the ogres of the Gordok wing and use it to free Knot Thimblejack." } },
    [5526] = { objective = { from = "legacy", text = "Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade." } },
    [5527] = { objective = { from = "legacy", text = "Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade." } },
    [5529] = { objective = { from = "legacy", text = "Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel." } },
    [5531] = { objective = { from = "legacy", text = "Bring the Frozen Eggs to Betina Bigglezink." } },
    [5542] = { objective = { from = "legacy", text = "Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete." } },
    [5543] = { objective = { from = "legacy", text = "Slay 30 Plaguebats and return to Tirion Fordring." } },
    [5544] = { objective = { from = "legacy", text = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat." } },
    [5723] = { objective = { from = "legacy", text = "Kill 8 Ragefire Troggs and 8 Ragefire Shamans inside Ragefire Chasm." } },
    [5724] = { hints = { { field = "startedBy", from = "legacy", text = "Grimtotem Satchel, taken from Maur Grimtotem's corpse inside Ragefire Chasm" } }, objective = { from = "legacy", text = "Take the Grimtotem Satchel to Rahauro in Thunder Bluff." } },
    [5725] = { objective = { from = "legacy", text = "Collect Spells of Shadow and Incantations from the Nether inside Ragefire Chasm." } },
    [5726] = { description = { from = "legacy", text = "First required Hidden Enemies step for the Ragefire Chasm chain." }, objective = { from = "legacy", text = "Bring a Lieutenant's Insignia from the Burning Blade in Skull Rock to Thrall." } },
    [5727] = { description = { from = "legacy", text = "Neeru is in the Cleft of Shadow near the Ragefire Chasm entrance." }, objective = { from = "legacy", text = "Speak with Neeru Fireblade in the Cleft of Shadow, then return to Thrall." } },
    [5728] = { objective = { from = "legacy", text = "Kill Bazzalan and Jergosh the Invoker inside Ragefire Chasm." } },
    [5742] = { objective = { from = "legacy", text = "Listen to what Tirion Fordring has to say." } },
    [5761] = { objective = { from = "legacy", text = "Slay Taragaman the Hungerer and recover Taragaman the Hungerer's Heart." } },
    [5781] = { objective = { from = "legacy", text = "Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective." } },
    [5845] = { objective = { from = "legacy", text = "Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective." } },
    [5846] = { objective = { from = "legacy", text = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting." } },
    [5848] = { objective = { from = "legacy", text = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world. Return the painting to Tirion Fordring." } },
    [5961] = { objective = { from = "legacy", text = "Speak with Nathanos Blightcaller in the Eastern Plaguelands. He is said to have taken up residence at the Marris Stead." } },
    [6022] = { objective = { from = "legacy", text = "Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot." } },
    [6042] = { objective = { from = "legacy", text = "Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished." } },
    [6133] = { objective = { from = "legacy", text = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge. You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen." } },
    [6135] = { objective = { from = "legacy", text = "Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller. It is said that Duskwing roams the countryside to the north of Marris Stead." } },
    [6136] = { objective = { from = "legacy", text = "Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him. Return to Nathanos Blightcaller when the mission is complete." } },
    [6141] = { objective = { from = "legacy", text = "Speak with Brother Anton in Desolace." } },
    [6163] = { objective = { from = "legacy", text = "Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos." } },
    [6402] = { objective = { from = "legacy", text = "Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived." } },
    [6403] = { objective = { from = "legacy", text = "Follow Reginald Windsor through Stormwind. Protect him from harm!" } },
    [6501] = { objective = { from = "legacy", text = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist." } },
    [6502] = { objective = { from = "legacy", text = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire." } },
    [6521] = { objective = { from = "legacy", text = "Bring Ambassador Malcin's Head to Varimathras in the Undercity." } },
    [6522] = { hints = { { field = "startedBy", from = "legacy", text = "Dropped by Charlga Razorflank in Razorfen Kraul" }, { field = "startedBy", from = "legacy", text = "Small Scroll (drops from Charlga Razorflank in Razorfen Kraul)" } }, objective = { from = "legacy", text = "Take the Small Scroll to Varimathras in the Undercity." } },
    [6561] = { objective = { from = "legacy", text = "Defeat Twilight Lord Kelris and recover the Head of Kelris." } },
    [6562] = { objective = { from = "legacy", text = "Speak to Je'neu Sancrea in Ashenvale." } },
    [6564] = { hints = { { field = "startedBy", from = "legacy", text = "Drops from Blackfathom Tide Priestess in the entrance tunnels leading to Blackfathom Deeps." }, { field = "startedBy", from = "legacy", text = "Use the Damp Note dropped by Blackfathom Tide Priestesses" } }, objective = { from = "legacy", text = "Bring the Damp Note to Je'neu Sancrea in Ashenvale." } },
    [6565] = { objective = { from = "legacy", text = "Defeat Lorgus Jett in Blackfathom Deeps." } },
    [6566] = { objective = { from = "legacy", text = "Listen to Thrall." } },
    [6567] = { objective = { from = "legacy", text = "Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas." } },
    [6568] = { objective = { from = "legacy", text = "Deliver Rexxar's Testament to Myranda the Hag in the Western Plaguelands." } },
    [6569] = { objective = { from = "legacy", text = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete." } },
    [6570] = { objective = { from = "legacy", text = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife." } },
    [6582] = { objective = { from = "legacy", text = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife. You know that Scryer can be found in Winterspring." } },
    [6583] = { objective = { from = "legacy", text = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife." } },
    [6584] = { objective = { from = "legacy", text = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife." } },
    [6585] = { objective = { from = "legacy", text = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife." } },
    [6601] = { objective = { from = "legacy", text = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next." } },
    [6602] = { objective = { from = "legacy", text = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar." } },
    [6626] = { objective = { from = "legacy", text = "Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs." } },
    [6921] = { objective = { from = "legacy", text = "Recover the Fathom Core from the Fathom Stone in Blackfathom Deeps." } },
    [6922] = { hints = { { field = "startedBy", from = "legacy", text = "Strange Water Globe, dropped by Baron Aquanis inside Blackfathom Deeps" } }, objective = { from = "legacy", text = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale." } },
    [6981] = { hints = { { field = "endedBy", from = "legacy", text = "Follow the quest directions beginning in Ratchet" }, { field = "startedBy", from = "legacy", text = "Item start: Glowing Shard, dropped by Mutanus the Devourer" } }, objective = { from = "legacy", text = "Travel to Ratchet to find someone who can identify the Glowing Shard, then deliver it as directed." } },
    [7028] = { objective = { from = "legacy", text = "Collect 25 Theradric Crystal Carvings for Willow in Desolace." } },
    [7029] = { objective = { from = "legacy", text = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon. Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge. Heal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village." } },
    [7041] = { objective = { from = "legacy", text = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon. Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge. Heal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point." } },
    [7044] = { objective = { from = "legacy", text = "Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond. Find a way to speak with Celebras." } },
    [7046] = { objective = { from = "legacy", text = "Assist Celebras the Redeemed while he creates the Scepter of Celebras. Speak with him when the ritual is complete." } },
    [7064] = { objective = { from = "legacy", text = "Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace." } },
    [7065] = { objective = { from = "legacy", text = "Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace." } },
    [7066] = { objective = { from = "legacy", text = "Seek out Remulos in Moonglade and give him the Seed of Life." } },
    [7067] = { objective = { from = "legacy", text = "Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace." } },
    [7068] = { objective = { from = "legacy", text = "Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar." } },
    [7070] = { objective = { from = "legacy", text = "Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh." } },
    [7201] = { objective = { from = "legacy", text = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals." } },
    [7441] = { objective = { from = "legacy", text = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary. Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations." } },
    [7461] = { objective = { from = "legacy", text = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated. Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum. Return to the Shen'dralar Ancient in the courtyard should you complete this quest." } },
    [7463] = { objective = { from = "legacy", text = "Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence." } },
    [7481] = { objective = { from = "legacy", text = "Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find." } },
    [7482] = { objective = { from = "legacy", text = "Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find." } },
    [7483] = { objective = { from = "legacy", text = "Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity." } },
    [7484] = { objective = { from = "legacy", text = "Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus." } },
    [7485] = { objective = { from = "legacy", text = "Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection." } },
    [7488] = { objective = { from = "legacy", text = "Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas." } },
    [7489] = { objective = { from = "legacy", text = "Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas." } },
    [7492] = { objective = { from = "legacy", text = "Speak with Talo Thornhoof at Camp Mojache in Feralas." } },
    [7494] = { objective = { from = "legacy", text = "Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas." } },
    [7498] = { hints = { { field = "startedBy", from = "legacy", text = "Garona: A Study on Stealth and Treachery (book, Dire Maul drop)" } }, objective = { from = "legacy", text = "Return the book to its rightful owners." } },
    [7499] = { hints = { { field = "startedBy", from = "legacy", text = "Codex of Defense (book, Dire Maul drop)" } }, objective = { from = "legacy", text = "Return the book to its rightful owners." } },
    [7500] = { hints = { { field = "startedBy", from = "legacy", text = "The Arcanist's Cookbook (book, Dire Maul drop)" } }, objective = { from = "legacy", text = "Return the book to its rightful owners." } },
    [7501] = { hints = { { field = "startedBy", from = "legacy", text = "The Light and How To Swing It (book, Dire Maul drop)" } }, objective = { from = "legacy", text = "Return the book to its rightful owners." } },
    [7502] = { hints = { { field = "startedBy", from = "legacy", text = "Harnessing Shadows (book, Dire Maul drop)" } }, objective = { from = "legacy", text = "Return the book to its rightful owners." } },
    [7503] = { hints = { { field = "startedBy", from = "legacy", text = "The Greatest Race of Hunters (book, Dire Maul drop)" } }, objective = { from = "legacy", text = "Return the book to its rightful owners." } },
    [7504] = { hints = { { field = "startedBy", from = "legacy", text = "Holy Bologna: What the Light Won't Tell You (book, Dire Maul drop)" } }, objective = { from = "legacy", text = "Return the book to its rightful owners." } },
    [7505] = { hints = { { field = "startedBy", from = "legacy", text = "Frost Shock and You (book, Dire Maul drop)" } }, objective = { from = "legacy", text = "Return the book to its rightful owners." } },
    [7506] = { hints = { { field = "startedBy", from = "legacy", text = "The Emerald Dream (book, Dire Maul drop)" } }, objective = { from = "legacy", text = "Return the book to its rightful owners." } },
    [7507] = { hints = { { field = "startedBy", from = "legacy", text = "Nostro's Compendium of Dragon Slaying (rare Dire Maul drop)" } }, objective = { from = "legacy", text = "Return Nostro's Compendium of Dragon Slaying to the Athenaeum." } },
    [7563] = { objective = { from = "legacy", text = "Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes." } },
    [7564] = { objective = { from = "legacy", text = "Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes." } },
    [7604] = { hints = { { field = "startedBy", from = "legacy", text = "Thorium Brotherhood Contract (from Lokhtos Darkbargainer with a Sulfuron Ingot)" } }, objective = { from = "legacy", text = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron." } },
    [7623] = { objective = { from = "legacy", text = "Purchase Shadowy Potions from Gorzeeki in the Burning Steppes. Use the potions to travel through Jaedenar, and speak with Lord Banehollow." } },
    [7624] = { objective = { from = "legacy", text = "Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar." } },
    [7625] = { objective = { from = "legacy", text = "Purchase Xorothian Stardust from Ur'dan. Bring it to Gorzeeki Wildeyes in the Burning Steppes." } },
    [7626] = { objective = { from = "legacy", text = "Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes." } },
    [7627] = { objective = { from = "legacy", text = "Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes." } },
    [7628] = { objective = { from = "legacy", text = "Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes." } },
    [7629] = { objective = { from = "legacy", text = "Bring the Imp in a Jar to the alchemy lab in the Scholomance. After the parchment is created, return the jar to Gorzeeki Wildeyes." } },
    [7630] = { objective = { from = "legacy", text = "Bring 3 Arcanite Bars to Gorzeeki in the Burning Steppes." } },
    [7631] = { objective = { from = "legacy", text = "Read Mor'zul's Instructions. Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you." } },
    [7637] = { objective = { from = "legacy", text = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it." } },
    [7639] = { objective = { from = "legacy", text = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." } },
    [7640] = { objective = { from = "legacy", text = "Use the Exorcism Censer to drive out the spirits that torment Terrordale. When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." } },
    [7641] = { objective = { from = "legacy", text = "Speak with Grimand Elmore in Stormwind's Dwarven District." } },
    [7642] = { objective = { from = "legacy", text = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind." } },
    [7643] = { objective = { from = "legacy", text = "Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food. Travel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it." } },
    [7644] = { objective = { from = "legacy", text = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." } },
    [7645] = { objective = { from = "legacy", text = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills. The Argent Dawn is known as the sole purveyor of the biscuits. You also need to give her 50 gold to soothe her ruffled sensibilities." } },
    [7646] = { objective = { from = "legacy", text = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." } },
    [7647] = { objective = { from = "legacy", text = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger. Give the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger." } },
    [7648] = { objective = { from = "legacy", text = "Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection." } },
    [7667] = { objective = { from = "legacy", text = "If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond." } },
    [7668] = { objective = { from = "legacy", text = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him. Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar." } },
    [7703] = { objective = { from = "legacy", text = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul. According to Kromcrush, the \\\"old timey story\\\" says that Tortheldrin - a \\\"creepy\\\" elf who called himself a prince - stole it from one of the Gordok kings." } },
    [7761] = { hints = { { field = "endedBy", from = "legacy", text = "Drakkisath's Brand, Upper Blackrock Spire" }, { field = "startedBy", from = "legacy", text = "Blackhand's Command (letter from the Scarshield Quartermaster, Blackrock Mountain)" } }, objective = { from = "legacy", text = "Find the brand that General Drakkisath guards and gain the Mark of Drakkisath, so you can use the Orb of Command." } },
    [8151] = { hints = { { field = "startedBy", from = "legacy", text = "Hunter trainers" } }, objective = { from = "legacy", text = "Speak to Ogtinc in Azshara." } },
    [8153] = { objective = { from = "legacy", text = "Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath." } },
    [8231] = { objective = { from = "legacy", text = "Bring 6 Wavethrasher Scales to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath." } },
    [8232] = { objective = { from = "legacy", text = "Bring the Tooth of Morphaz to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath." } },
    [8233] = { hints = { { field = "startedBy", from = "legacy", text = "Rogue trainers" } }, objective = { from = "legacy", text = "Speak with Lord Jorach Ravenholdt in Ravenholdt Manor." } },
    [8234] = { objective = { from = "legacy", text = "Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara. Then take the bag to Archmage Xylem, also found in Azshara." } },
    [8235] = { objective = { from = "legacy", text = "Bring 10 Encoded Fragments to Archmage Xylem in Azshara." } },
    [8236] = { objective = { from = "legacy", text = "Return the Azure Key to Lord Jorach Ravenholdt." } },
    [8250] = { hints = { { field = "startedBy", from = "legacy", text = "Mage trainers" } }, objective = { from = "legacy", text = "Seek out Sanath Lim-yo and gain passage to see Archmage Xylem." } },
    [8251] = { objective = { from = "legacy", text = "Bring 10 Glittering Dust to Archmage Xylem." } },
    [8252] = { objective = { from = "legacy", text = "Collect 6 Enchanted Coral and return them to Archmage Xylem." } },
